import { isDangerousActionText } from '@reticlehq/core';
import { getAccessibleName } from '../dom/a11y.js';
const LABEL_VALUED_INPUT_TYPES = new Set([
    'submit',
    'button',
    'reset',
    'image',
]);
function holdsUserText(el) {
    if (el.isContentEditable)
        return true;
    if (el instanceof HTMLTextAreaElement)
        return true;
    if (el instanceof HTMLInputElement)
        return !LABEL_VALUED_INPUT_TYPES.has(el.type.toLowerCase());
    return false;
}
export function dangerousActionContext(el) {
    const form = el.closest('form');
    const ownText = holdsUserText(el)
        ? ['', '']
        : [el.textContent ?? '', el.getAttribute('value') ?? ''];
    return [
        getAccessibleName(el),
        ...ownText,
        el.getAttribute('title') ?? '',
        el.getAttribute('aria-label') ?? '',
        el.getAttribute('href') ?? '',
        form?.getAttribute('action') ?? '',
    ].join(' ');
}
const SUBMIT_CONTROL_SELECTOR = 'button[type="submit"], input[type="submit"], button:not([type]):not([type=""])';
export function submitControlFor(el) {
    const found = el.closest('form')?.querySelector(SUBMIT_CONTROL_SELECTOR);
    return found instanceof HTMLElement ? found : null;
}
export function requiresDangerousConfirmation(text, role) {
    return isDangerousActionText(text, role);
}
